package hu.synostream.android;
import org.junit.*;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.atomic.*;
public class NasClientRoutesTest {
 NasClientTest local,remote,relay;AtomicInteger resolutions;
 @Before public void start()throws Exception{local=new NasClientTest();remote=new NasClientTest();relay=new NasClientTest();local.start();remote.start();relay.start();resolutions=new AtomicInteger();}
 @After public void stop()throws Exception{local.stop();remote.stop();relay.stop();}
 String address(NasClientTest f){return "http://127.0.0.1:"+f.server.getLocalPort();}
 NasClient client(String l,String d,String otp){return new NasClient(new NasClient.Credentials("fixture-qc",l,d,"fixture-qc","test","secret",otp),id->{assertEquals("fixture-qc",id);resolutions.incrementAndGet();return List.of(address(relay));});}
 @Test public void localWinsBeforeDdnsAndQuickConnect()throws Exception{NasClient c=client(address(local),address(remote),"");c.connect();assertEquals("Helyi kapcsolat",c.route);assertEquals(1,local.logins);assertEquals(0,remote.logins);assertEquals(0,resolutions.get());}
 @Test public void failedLocalFallsBackToDdnsWithoutQuickConnect()throws Exception{String dead=address(local);local.stop();NasClient c=client(dead,address(remote),"");c.connect();assertEquals("DDNS",c.route);assertEquals(1,remote.logins);assertEquals(0,resolutions.get());}
 @Test public void failedDdnsFallsBackToQuickConnect()throws Exception{String a=address(local),b=address(remote);local.stop();remote.stop();NasClient c=client(a,b,"");c.connect();assertEquals("QuickConnect",c.route);assertEquals(1,relay.logins);assertEquals(1,resolutions.get());}
 @Test public void mobileNeverCallsOptionalLocal()throws Exception{NasClient c=client(address(local),address(remote),"");c.connect(false);assertEquals("DDNS",c.route);assertEquals(0,local.logins);assertEquals(1,remote.logins);}
 @Test public void mobileDdnsFailureUsesQuickConnect()throws Exception{String dead=address(remote);remote.stop();NasClient c=client(address(local),dead,"");c.connect(false);assertEquals("QuickConnect",c.route);assertEquals(0,local.logins);assertEquals(1,resolutions.get());}
 @Test public void probesEachRouteWithoutOtpOrSharingLoginSession()throws Exception{NasClient c=client(address(local),address(remote),"123456");List<NasClient.ConnectionCheck> rows=c.checkConnections(true);assertEquals(3,rows.size());for(NasClient.ConnectionCheck row:rows)assertEquals(NasClient.CheckStatus.SUCCESS,row.status);for(NasClientTest f:List.of(local,remote,relay)){assertEquals("",f.lastOtp);assertTrue(f.lastSession.startsWith("SynoStreamCheck_"));}assertNotEquals(local.lastSession,remote.lastSession);assertEquals("",c.route);}
 @Test public void mobileProbeReportsSkippedLocal()throws Exception{List<NasClient.ConnectionCheck> rows=client(address(local),address(remote),"").checkConnections(false);assertEquals(NasClient.CheckStatus.SKIPPED,rows.get(0).status);assertEquals(0,local.logins);assertEquals(NasClient.CheckStatus.SUCCESS,rows.get(1).status);}
 @Test public void probeCanReportOnlyLocalAsSkippedOnMobile()throws Exception{NasClient c=new NasClient(new NasClient.Credentials("",address(local),"","","test","secret",""));assertEquals(NasClient.CheckStatus.SKIPPED,c.checkConnections(false).get(0).status);assertEquals(0,local.logins);}
 @Test public void authenticationFailureDoesNotSprayCredentialsAcrossOtherRoutes()throws Exception{local.rejectLogins=true;assertThrows(SecurityException.class,()->client(address(local),address(remote),"").connect());assertEquals(0,remote.logins);assertEquals(0,resolutions.get());}
 @Test public void ambiguousOtpLoginIsNotReplayedAtNextEndpoint()throws Exception{local.dropAuthResponse=true;assertThrows(SecurityException.class,()->client(address(local),address(remote),"123456").connect());assertEquals("123456",local.lastOtp);assertEquals(0,remote.logins);}
 @Test public void reconnectUsesLatestSavedEndpoints()throws Exception{NasClient root=client(address(local),address(remote),"");root.connect();NasClient changed=new NasClient(new NasClient.Credentials(address(relay),"","","","test","secret",""));changed.connect();int token=root.suspendConnection();root.installConnection(token,changed);int before=relay.logins;root.reconnectCandidate(false);assertEquals(before+1,relay.logins);assertEquals(address(relay),root.settingsCredentials().address);assertEquals(1,local.logins);}
 @Test public void probesReportBadAuthenticationWithoutThrowing()throws Exception{remote.rejectLogins=true;remote.rejectLoginCode=400;List<NasClient.ConnectionCheck> rows=client(address(local),address(remote),"").checkConnections(true);assertEquals(NasClient.CheckStatus.AUTH_FAILED,rows.get(1).status);assertEquals(NasClient.CheckStatus.SUCCESS,rows.get(2).status);}
 @Test public void missingTwoStepCodeHasItsOwnCheckStatus()throws Exception{remote.rejectLogins=true;remote.rejectLoginCode=403;List<NasClient.ConnectionCheck> rows=client(address(local),address(remote),"").checkConnections(true);assertEquals(NasClient.CheckStatus.CODE_REQUIRED,rows.get(1).status);}
 @Test public void only403UsesOtpRequiredException()throws Exception{remote.rejectLogins=true;NasClient c=new NasClient(new NasClient.Credentials(address(remote),"","test","secret",""));assertThrows(NasClient.OtpRequiredException.class,c::connect);remote.rejectLoginCode=404;SecurityException expired=assertThrows(SecurityException.class,()->new NasClient(new NasClient.Credentials(address(remote),"","test","secret","")).connect());assertEquals(SecurityException.class,expired.getClass());}
 @Test public void unavailableAndSkippedAreNotAuthenticationErrors()throws Exception{String dead=address(remote);remote.stop();List<NasClient.ConnectionCheck> rows=client(address(local),dead,"").checkConnections(false);assertEquals(NasClient.CheckStatus.SKIPPED,rows.get(0).status);assertEquals(NasClient.CheckStatus.UNAVAILABLE,rows.get(1).status);assertEquals(NasClient.CheckStatus.SUCCESS,rows.get(2).status);}

}
